* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: #2d3e50;
  color: #ecf0f1;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background: #34495e;
  border-radius: 24px;
  padding: 24px;
  max-width: 400px;
  width: 100%;
  box-shadow: 0 8px 0 #1e2b38, 0 12px 24px rgba(0,0,0,0.3);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: #f1c40f;
  text-shadow: 2px 2px 0 #1e2b38;
  letter-spacing: 1px;
}

.pet-wrapper {
  width: 160px;
  height: 160px;
  display: flex;
  justify-content: center;
  align-items: flex-end;
}

.pet {
  position: relative;
  width: 100px;
  height: 120px;
  image-rendering: pixelated;
}

.head {
  position: relative;
  width: 80px;
  height: 60px;
  background: #e67e22;
  border-radius: 16px 16px 0 0;
  margin: 0 auto;
  box-shadow: 0 4px 0 #b35f1a;
}

.ear {
  position: absolute;
  width: 16px;
  height: 24px;
  background: #e67e22;
  border-radius: 8px 8px 0 0;
  top: -16px;
  box-shadow: 0 4px 0 #b35f1a;
}

.ear.left {
  left: 0;
  transform: rotate(-10deg);
}

.ear.right {
  right: 0;
  transform: rotate(10deg);
}

.face {
  position: absolute;
  bottom: 8px;
  left: 50%;
  transform: translateX(-50%);
  width: 60px;
  height: 32px;
}

.eye {
  position: absolute;
  width: 10px;
  height: 10px;
  background: #2c3e50;
  border-radius: 50%;
  top: 0;
}

.eye.left {
  left: 8px;
}

.eye.right {
  right: 8px;
}

.mouth {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 20px;
  height: 8px;
  border-bottom: 4px solid #2c3e50;
  border-radius: 0 0 50% 50%;
}

.body {
  width: 80px;
  height: 60px;
  background: #e67e22;
  border-radius: 0 0 16px 16px;
  margin: 0 auto;
  box-shadow: 0 4px 0 #b35f1a;
}

.mood {
  font-size: 1.25rem;
  font-weight: 600;
  color: #f1c40f;
  text-shadow: 1px 1px 0 #1e2b38;
}

.stats {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat label {
  font-size: 0.875rem;
  font-weight: 600;
  color: #bdc3c7;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.bar-container {
  height: 20px;
  background: #1e2b38;
  border-radius: 10px;
  overflow: hidden;
  box-shadow: inset 0 2px 4px rgba(0,0,0,0.4);
}

.bar {
  height: 100%;
  width: 50%;
  border-radius: 10px;
  transition: width 0.3s ease;
}

.bar.hunger {
  background: #e74c3c;
}

.bar.happiness {
  background: #f1c40f;
}

.bar.energy {
  background: #2ecc71;
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 20px;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  color: #2c3e50;
  background: #ecf0f1;
  box-shadow: 0 4px 0 #bdc3c7;
  transition: transform 0.1s, box-shadow 0.1s;
  min-width: 80px;
  text-align: center;
}

.btn:hover {
  background: #ffffff;
}

.btn:focus-visible {
  outline: 3px solid #f1c40f;
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 #bdc3c7;
}

.btn.feed {
  background: #e74c3c;
  color: #fff;
  box-shadow: 0 4px 0 #b03a2e;
}

.btn.feed:hover {
  background: #ec7063;
}

.btn.play {
  background: #f1c40f;
  color: #2c3e50;
  box-shadow: 0 4px 0 #b7950b;
}

.btn.play:hover {
  background: #f4d03f;
}

.btn.sleep {
  background: #2ecc71;
  color: #2c3e50;
  box-shadow: 0 4px 0 #239b56;
}

.btn.sleep:hover {
  background: #58d68d;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  .btn {
    padding: 10px 16px;
    font-size: 0.875rem;
    min-width: 70px;
  }
}

const state = {
  hunger: 50,
  happiness: 50,
  energy: 50
};

const moodEl = document.getElementById('mood');
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');

function updateUI() {
  hungerBar.style.width = state.hunger + '%';
  hungerBar.setAttribute('aria-valuenow', state.hunger);
  happinessBar.style.width = state.happiness + '%';
  happinessBar.setAttribute('aria-valuenow', state.happiness);
  energyBar.style.width = state.energy + '%';
  energyBar.setAttribute('aria-valuenow', state.energy);

  const avg = (state.hunger + state.happiness + state.energy) / 3;
  let mood = 'Happy';
  if (avg < 20) mood = 'Sad';
  else if (avg < 40) mood = 'Meh';
  else if (avg > 80) mood = 'Ecstatic';
  else if (avg > 60) mood = 'Content';
  moodEl.textContent = 'Mood: ' + mood;
}

function clamp(val) {
  return Math.max(0, Math.min(100, val));
}

document.getElementById('feed-btn').addEventListener('click', () => {
  state.hunger = clamp(state.hunger + 20);
  state.happiness = clamp(state.happiness + 5);
  state.energy = clamp(state.energy - 5);
  updateUI();
});

document.getElementById('play-btn').addEventListener('click', () => {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
});

document.getElementById('sleep-btn').addEventListener('click', () => {
  state.energy = clamp(state.energy + 25);
  state.hunger = clamp(state.hunger - 5);
  state.happiness = clamp(state.happiness - 5);
  updateUI();
});

updateUI();
